<?php require 'config.php';$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,name,price FROM products WHERE id IN ($in)");$s->execute($ids);$items=$s->fetchAll();} ?><h1>Shopping Cart</h1><table border="1" cellpadding="8"><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th></tr><?php foreach($items as $p):$qty=$cart[$p['id']];$sub=$qty*(float)$p['price'];$total+=$sub;?><tr><td><?=h($p['name'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$qty?></td><td>₹<?=number_format($sub,2)?></td></tr><?php endforeach?></table><h3>Total: ₹<?=number_format($total,2)?></h3><?php if(!$items):?><p>Your cart is empty. Add products from the home page.</p><?php endif?><a href="index.php">Continue shopping</a> | <a href="cart_clear.php">Clear cart</a>